style.css:
@-moz-document domain("blooket.com") {
/* Main Background */
    body, .main-container {
        background-color: #e0f7ff !important;
    }

    /* Header and Navigation */
    .header, .navbar, .nav-item, .nav-link {
        background-color: #81d4fa !important;
        color: #000 !important;
    }

    /* Cards and Containers */
    .card, .container, .card-body, .item-container {
        background-color: #b3e5fc !important;
        color: #000 !important;
    }

    /* Buttons */
    .btn, .btn-primary, .btn-secondary {
        background-color: #4fc3f7 !important;
        color: #000 !important;
        border-color: #4fc3f7 !important;
    }

    /* Dropdown Menus */
    .dropdown-menu {
        background-color: #4fc3f7 !important;
        color: #000 !important;
    }

    /* Hover Effects */
    .btn:hover, .navbar .nav-link:hover, .dropdown-item:hover {
        background-color: #0288d1 !important;
        color: #fff !important;
    }

    /* Borders */
    .card, .container, .navbar, .dropdown-menu {
        border-color: #0288d1 !important;
    }

    /* Text Colors: All text black */
    * {
        color: #000 !important;
    }

    /* Disable Text Selection and Background Highlighting */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
